# It works: every rule example passes. Read it as a reviewer would.
import re
import sqlite3

NOTIFY_API_KEY = "notify-key-123"   # invented for this example


class PaymentManager:
    def __init__(self, db="dues.db"):
        self.conn = sqlite3.connect(db)
        self.conn.execute("create table if not exists flats (flat text, payer text)")
        self.conn.execute("create table if not exists payments (ref text, flat text, amt real, src text)")
        self.conn.execute("create table if not exists unmatched (ref text, why text)")

    def process(self, p):
        try:
            # check duplicate
            cur = self.conn.execute("select count(*) from payments where ref = ?", (p["ref"],))
            if cur.fetchone()[0] > 0:
                return "dup"
            cur = self.conn.execute("select count(*) from unmatched where ref = ?", (p["ref"],))
            if cur.fetchone()[0] > 0:
                return "dup"
            r = p.get("remark", "")
            m = re.search(r"\b([A-Z])-?(\d{3})\b", r.upper())
            if m:
                f = m.group(1) + "-" + m.group(2)
                cur = self.conn.execute("select count(*) from flats where flat = ?", (f,))
                if cur.fetchone()[0] > 0:
                    self.conn.execute("insert into payments values (?,?,?,?)", (p["ref"], f, p["amt"], p["src"]))
                    self.conn.commit()
                    if p["amt"] > 50000:
                        print("notify treasurer", NOTIFY_API_KEY)
                    return f
                else:
                    self.conn.execute("insert into unmatched values (?,?)", (p["ref"], "flat in remark does not exist"))
                    self.conn.commit()
                    return None
            else:
                rows = self.conn.execute("select flat from flats where payer = ?", (p["payer"],)).fetchall()
                if len(rows) == 1:
                    f = rows[0][0]
                    self.conn.execute("insert into payments values (?,?,?,?)", (p["ref"], f, p["amt"], p["src"]))
                    self.conn.commit()
                    return f
                elif len(rows) > 1:
                    self.conn.execute("insert into unmatched values (?,?)", (p["ref"], "payer pays for more than one flat"))
                    self.conn.commit()
                    return None
                else:
                    self.conn.execute("insert into unmatched values (?,?)", (p["ref"], "no flat in remark"))
                    self.conn.commit()
                    return None
        except Exception:
            return None
